// Declare the NeonToolkits interface
export const addToEscapeKeyStack = (node) => {
    // console.log('adding to escape stack', node);
    if (!neonToolkitHas('neon-all-versions-escape-key-stack')) {
        addNeonToolkit('neon-all-versions-escape-key-stack', []);
    }
    const escapeStack = getNeonToolkit('neon-all-versions-escape-key-stack');
    // Toasts and system messages have the highest priority in the escape key stack
    // If the node is a toast or system message, add it to the end of the stack
    if (node instanceof Element && (node.hasAttribute('neon-toast') || node.hasAttribute('neon-system-message'))) {
        escapeStack.push(node);
        // console.log('added message to escape stack', node);
        // convertEscapeKeyStackToTagArray(escapeStack);
        return;
    }
    else {
        // If the node is not a toast, system message, or detail layout find the index of the last toast or system message in the stack
        const messageIndex = escapeStack.findIndex((node) => { return node instanceof Element && (node.hasAttribute('neon-toast') || node.hasAttribute('neon-system-message')); });
        // If no toast or system message is found, add the node to the end of the stack
        if (messageIndex === -1) {
            escapeStack.push(node);
            // console.log('added non-message to messageless stack');
            // convertEscapeKeyStackToTagArray(escapeStack);
            return;
        }
        escapeStack.splice(messageIndex, 0, node);
        // console.log('added non-message positioned to escape stack');
        // convertEscapeKeyStackToTagArray(escapeStack);
        return;
    }
};
export const isTopOfEscapeKeyStack = (node) => {
    const escapeStack = getNeonToolkit('neon-all-versions-escape-key-stack');
    return this === escapeStack.at(-1) || node === escapeStack.at(-1);
};
export const removeFromEscapeKeyStack = (node) => {
    if (!neonToolkitHas('neon-all-versions-escape-key-stack')) {
        return;
    }
    const escapeStack = getNeonToolkit('neon-all-versions-escape-key-stack');
    setTimeout(() => {
        // console.log('removing from escape stack', node);
        const index = escapeStack.indexOf(node);
        if (index !== -1) {
            escapeStack.splice(index, 1);
            // console.log('removed from escape stack');
            // convertEscapeKeyStackToTagArray(escapeStack);
        }
    });
};
